CREATE TABLE IF NOT EXISTS disc_medicine_articles (
    id INT PRIMARY KEY,
    slug VARCHAR(160) NOT NULL UNIQUE,
    title VARCHAR(255) NOT NULL,
    therapeutic_area VARCHAR(120) NOT NULL,
    program VARCHAR(80) NOT NULL,
    indication_name VARCHAR(160) NOT NULL,
    article_date DATE NOT NULL,
    summary TEXT NOT NULL,
    body LONGTEXT NOT NULL,
    source_name VARCHAR(160) NOT NULL,
    source_url VARCHAR(500) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

INSERT INTO disc_medicine_articles
(id, slug, title, therapeutic_area, program, indication_name, article_date, summary, body, source_name, source_url)
VALUES
(1, 'disc-medicine-hematology-platform', 'Disc Medicine and the Hematology Innovation Landscape', 'Hematology', 'Pipeline Overview', 'Blood disorders', '2026-01-01', 'Disc Medicine is a clinical-stage biopharmaceutical company focused on hematologic diseases, including rare genetic blood disorders and anemias associated with chronic disease.', 'Disc Medicine frames its work around hematology and the biology of red blood cell production, heme biosynthesis, and iron homeostasis. Its public pipeline includes programs designed either to modulate heme biosynthesis, increase iron availability through hepcidin suppression, or restrict iron through hepcidin induction. This makes the company relevant to RAG systems that need to organize clinical, translational, and investor-facing knowledge across rare blood disorders, chronic inflammatory anemia, and myeloproliferative disease. Key areas include erythropoietic protoporphyria, X-linked protoporphyria, Diamond Blackfan anemia, anemia of myelofibrosis, inflammatory bowel disease-associated anemia, non-dialysis-dependent chronic kidney disease anemia, polycythemia vera, and sickle cell disease.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(2, 'bitopertin-epp-xlp-heme-biosynthesis', 'Bitopertin, Heme Biosynthesis, and EPP/XLP', 'Heme biosynthesis', 'Bitopertin', 'Erythropoietic protoporphyria and X-linked protoporphyria', '2026-01-01', 'Bitopertin is listed by Disc Medicine as a GlyT1 inhibitor in development for erythropoietic protoporphyria and X-linked protoporphyria.', 'Erythropoietic protoporphyria and X-linked protoporphyria are disorders in which protoporphyrin IX can accumulate and produce severe photosensitivity. Disc Medicine lists bitopertin as a GlyT1 inhibitor and heme biosynthesis modulator, with EPP and XLP in Phase 3 and an APOLLO study initiated according to the company pipeline page. In a knowledge base, bitopertin content should connect mechanism, biomarker rationale, clinical endpoints related to PPIX and light tolerance, patient burden, and trial-stage caveats. Content should avoid presenting investigational therapies as approved products.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(3, 'protoporphyrin-ix-photosensitivity', 'Why Protoporphyrin IX Matters in Protoporphyria', 'Porphyria biology', 'Bitopertin', 'EPP and XLP', '2026-01-01', 'Protoporphyrin IX is central to the clinical biology of EPP and XLP because excess photoactive material can drive painful light sensitivity.', 'In EPP and XLP, protoporphyrin IX is a biologically important intermediate because accumulation in blood and tissues can lead to phototoxic reactions after light exposure. A Disc Medicine-oriented article library should represent PPIX as both a disease biology concept and a clinical development biomarker. For RAG use, useful metadata includes indication, mechanism class, clinical endpoint, patient-reported burden, and whether text is patient-facing, medical-facing, or investor-facing.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(4, 'disc-0974-hepcidin-suppression-mf-anemia', 'DISC-0974 and Hepcidin Suppression in Myelofibrosis Anemia', 'Iron homeostasis', 'DISC-0974', 'Anemia of myelofibrosis', '2026-01-01', 'DISC-0974 is listed as an anti-HJV monoclonal antibody designed to suppress hepcidin and increase iron availability.', 'Disc Medicine lists DISC-0974 as an anti-HJV monoclonal antibody in the hepcidin suppression category. Hepcidin is a master regulator of iron distribution, and high inflammatory hepcidin signaling can limit iron availability for erythropoiesis. In myelofibrosis-associated anemia, a RAG article should connect disease context, iron restriction biology, hepcidin suppression, and clinical-stage status. Disc Medicine lists anemia of myelofibrosis in Phase 2 for DISC-0974 on its pipeline page.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(5, 'hepcidin-inflammatory-anemia', 'Hepcidin as a Bridge Between Inflammation and Anemia', 'Iron homeostasis', 'DISC-0974', 'Anemia of inflammatory disease', '2026-01-01', 'Hepcidin biology links inflammation, iron sequestration, and reduced iron availability for red blood cell production.', 'Inflammatory signaling can increase hepcidin and reduce circulating iron availability, contributing to anemia in chronic disease settings. Disc Medicine has positioned hepcidin suppression programs as a way to increase iron availability. A company knowledge base can use this topic to connect mechanistic science with indications such as myelofibrosis anemia, inflammatory bowel disease anemia, and chronic kidney disease anemia. This article is educational and does not describe an approved treatment claim.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(6, 'ibd-anemia-iron-availability', 'IBD-Associated Anemia and Iron Availability', 'Anemia of inflammation', 'DISC-0974', 'Anemia of inflammatory bowel disease', '2026-01-01', 'Disc Medicine lists anemia of inflammatory bowel disease as a Phase 2 indication for DISC-0974.', 'Anemia in inflammatory bowel disease can involve bleeding, iron deficiency, inflammation-mediated iron restriction, and impaired erythropoiesis. Disc Medicine lists DISC-0974 for anemia of IBD in Phase 2. For RAG ingestion, IBD anemia content should preserve distinctions between absolute iron deficiency and functional iron restriction while linking to the broader hepcidin suppression rationale. Metadata should include inflammatory disease, anemia, hepcidin, and clinical development stage.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(7, 'ckd-anemia-non-dialysis-disc-0974', 'Non-Dialysis CKD Anemia in the Disc Medicine Pipeline Context', 'Anemia of chronic disease', 'DISC-0974', 'Anemia of non-dialysis-dependent chronic kidney disease', '2026-01-01', 'Disc Medicine lists anemia of non-dialysis-dependent CKD as a Phase 1 indication for DISC-0974.', 'Chronic kidney disease anemia is multifactorial and may involve reduced erythropoietin signaling, inflammation, iron restriction, and comorbidity burden. Disc Medicine lists non-dialysis-dependent CKD anemia in Phase 1 for DISC-0974. In a knowledge warehouse, CKD anemia content should be tagged separately from myelofibrosis anemia and IBD anemia because clinical context, endpoints, standards of care, and risk considerations differ.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(8, 'disc-3405-hepcidin-induction-polycythemia-vera', 'DISC-3405, TMPRSS6, and Hepcidin Induction in Polycythemia Vera', 'Iron restriction', 'DISC-3405', 'Polycythemia vera', '2026-01-01', 'DISC-3405 is listed as an anti-TMPRSS6 monoclonal antibody intended to induce hepcidin and restrict iron.', 'Disc Medicine lists DISC-3405 as an anti-TMPRSS6 monoclonal antibody in the hepcidin induction category. The strategic contrast with DISC-0974 is important: DISC-0974 aims to suppress hepcidin and increase iron availability, while DISC-3405 aims to induce hepcidin and restrict iron. Disc Medicine lists polycythemia vera in Phase 2 for DISC-3405. A RAG system should preserve that directional biology because confusing hepcidin induction and suppression would create clinically meaningful misinformation.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(9, 'disc-3405-sickle-cell-disease-iron-biology', 'Sickle Cell Disease and Iron Biology in the DISC-3405 Context', 'Hemoglobinopathy', 'DISC-3405', 'Sickle cell disease', '2026-01-01', 'Disc Medicine lists sickle cell disease as a Phase 1 indication under DISC-3405.', 'Sickle cell disease is a hemoglobinopathy with complex biology involving hemolysis, vaso-occlusion, inflammation, anemia, and complications that differ across patients. Disc Medicine lists sickle cell disease in Phase 1 for DISC-3405. Knowledge content for this area should avoid oversimplifying sickle cell disease as only an iron disorder; instead, it should present iron biology as one mechanistic angle within a broader hematologic disease context.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline'),
(10, 'biotech-rag-governance-disc-medicine', 'RAG Governance for Disc Medicine-Style Hematology Knowledge', 'Knowledge operations', 'RAG', 'Medical affairs and research operations', '2026-01-01', 'A Disc Medicine-style RAG system should distinguish investigational pipeline facts, patient education, medical information, and internal scientific notes.', 'A production RAG system for a hematology-focused biotech should include source attribution, role-based access, freshness metadata, and careful separation between investigational pipeline material and approved-label information. For Disc Medicine-related content, metadata should capture program, mechanism, indication, audience, source URL, publication date, and review status. Retrieval filters are especially important when users ask about patient-facing content, medical information, investor communications, or internal research notes.', 'Disc Medicine Pipeline', 'https://www.discmedicine.com/pipeline')
ON DUPLICATE KEY UPDATE
    title = VALUES(title),
    therapeutic_area = VALUES(therapeutic_area),
    program = VALUES(program),
    indication_name = VALUES(indication_name),
    article_date = VALUES(article_date),
    summary = VALUES(summary),
    body = VALUES(body),
    source_name = VALUES(source_name),
    source_url = VALUES(source_url),
    updated_at = CURRENT_TIMESTAMP;
